	'messages:apihelp-purge-example-simple' => 'en:Purge <kbd>[[{{MediaWiki:Mainpage}}]]</kbd> and the <kbd>API</kbd> page.',
	'messages:apihelp-purge-example-generator' => 'en:Purge the first 10 pages in the main namespace.',
