	'messages:apihelp-query+allcategories-example-generator' => 'en:Retrieve info about the category page itself for categories beginning <kbd>List</kbd>.',
	'messages:apihelp-query+alldeletedrevisions-summary' => 'en:List all deleted revisions by a user or in a namespace.',
